const now=()=>typeof performance!=='undefined'?performance.now():Date.now();
const round=(v:number,d=6)=>Math.round(v*10**d)/10**d;
const numeric=(v:unknown):number|null=>{const n=Number(v);return Number.isFinite(n)?n:null};
