function fnv1a(input:string){let hash=0x811c9dc5;for(let i=0;i<input.length;i++){hash^=input.charCodeAt(i);hash=Math.imul(hash,0x01000193)>>>0;}return`fnv1a32:${hash.toString(16).padStart(8,'0')}`}
